// services/pricebook-service/internal/domain/spatial/projection_test.go
package spatial_test

import (
	"testing"

	"github.com/Will413028/hawkr/pricebook-service/internal/domain/spatial"
	"github.com/stretchr/testify/require"
)

// Golden values generated by running Hawkr_Transformer_Pricebook@2b64d9b's
// actual wgs84_to_twd97_tm2 (spatial/interpolation.py) via:
//
//	python3 -c "from hawkr_price_ai.spatial.interpolation import wgs84_to_twd97_tm2; \
//	  print(wgs84_to_twd97_tm2(121.537226, 25.068013, epsg=3826))"
//
// This is not a hand-derived value — it is the reference implementation's own output,
// so any mismatch here is a Go-port bug, not a fixture error.
func TestWGS84ToTWD97TM2_MatchesPythonReference(t *testing.T) {
	cases := []struct {
		name         string
		lon, lat     float64
		epsg         int
		wantX, wantY float64
	}{
		{"taipei_no2_market_epsg3826", 121.537226, 25.068013, 3826, 304198.2130069592, 2773418.4999248073},
		{"moa_400_produce_epsg3826", 120.658677, 24.199409, 3826, 215326.83438373555, 2677149.725014327},
		{"moa_400_flower_epsg3826", 120.633526002155, 24.1476822435762, 3826, 212756.8521048087, 2671427.3951530987},
		{"central_meridian_epsg3826", 121.0, 24.0, 3826, 250000.0, 2655023.124963877},
		{"kinmen_epsg3825", 118.3, 24.43, 3825, 179018.3500578402, 2702825.073307725},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			x, y, err := spatial.WGS84ToTWD97TM2(tc.lon, tc.lat, tc.epsg)
			require.NoError(t, err)
			require.InDelta(t, tc.wantX, x, 1e-6)
			require.InDelta(t, tc.wantY, y, 1e-6)
		})
	}
}

func TestTWD97TM2ToWGS84_RoundTrips(t *testing.T) {
	cases := []struct {
		name     string
		lon, lat float64
		epsg     int
	}{
		{"taipei_no2_market", 121.537226, 25.068013, 3826},
		{"moa_400_produce", 120.658677, 24.199409, 3826},
		{"kinmen", 118.3, 24.43, 3825},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			x, y, err := spatial.WGS84ToTWD97TM2(tc.lon, tc.lat, tc.epsg)
			require.NoError(t, err)
			lon2, lat2, err := spatial.TWD97TM2ToWGS84(x, y, tc.epsg)
			require.NoError(t, err)
			require.InDelta(t, tc.lon, lon2, 1e-6)
			require.InDelta(t, tc.lat, lat2, 1e-6)
		})
	}
}

func TestWGS84ToTWD97TM2_RejectsUnsupportedEPSG(t *testing.T) {
	_, _, err := spatial.WGS84ToTWD97TM2(121.0, 24.0, 3857)
	require.Error(t, err)
}
